def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n):
        if coeffs[i] != 0:
            term = ""
            if coeffs[i] < 0:
                term = "-"
            else:
                if coeffs[i] == 1 and i != 0:
                    term += "x"
                else:
                    term += str(abs(coeffs[i]))
            if i != 0:
                term += "x^" + str(i)
            terms.append(term)
    return " ".join(terms)

def decode(encoded, original, message):
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i, j in zip(encoded, original):
        if i not in mapping:
            mapping[i] = j
        elif mapping[i] != j:
            return "Failed"

    # Check if the mapping is complete and there are no contradictions
    if len(mapping) != len(encoded):
        return "Failed"

    # Use the mapping to decode the message
    decoded = ""
    for i in message:
        if i in mapping:
            decoded += mapping[i]
        else:
            return "Failed"

    return decoded

