def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num in [2, 3]:
        return True
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def generate_numbers(n, rules):
    unique_numbers = set()
    queue = [[n]]

    while queue:
        current_number = queue.pop(0)
        for rule in rules:
            new_number = current_number[:]
            for i, digit in enumerate(new_number):
                if digit == rule[0]:
                    new_number[i] = rule[1]
                    break
            new_number = "".join(map(str, new_number))
            if new_number not in unique_numbers:
                unique_numbers.add(new_number)
                queue.append(new_number)

    return len(unique_numbers)

